-- aar/w3/aar_row_633_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 633 (the row's re-call line names why each round was sent back) and its ask_aar_builders row.
-- Every value is from Wall 11996, 11998, 12000, 12010 and 12011 (read whole by W3), ask633/w4/plan633.md rev 0 (read whole), ask633/w4/write/write633_run.txt (last lines), the card as stored in W4's thread (read by W3), and md5sum by W3 of the files named.
-- NOT READ by W3: audit_log row 42142; the live Build Save Body code; n8n; the grade files of W1 in git; the 59 and 30 line counts of the plan (W1 did not check them either).
-- objective_met is 'in part': written and read back; no run since the write.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (633, '0', $t$ASK 633: the row's re-call line names why each round was sent back$t$,
  $t$Every round re-call was recorded in the row as "[AUDIT v47: BARRED MOVE RE-CALL (pkgBAR) ... SENT BACK: <n> sentence(s) ...]", where n is the barred-sentence count alone. A round is also sent back for Oracle layer points (pkgLAYB) and, on D4B only, for pressed verses with no ANSWER line (ASK 628), so such a re-call read as a barred-move re-call that sent back 0 sentences. Change, in Build Save Body only: the line reads "[AUDIT v47: ROUND RE-CALL (pkgBAR, pkgLAYB) -- SEAT: ...; ROUND: [..]; SENT BACK: <n> barred sentence(s); <m> layer point(s)[; <k> pressed verse(s) with no ANSWER line]; KEPT: ...; VOID: ...]"; the pressed-verse part is printed only for CR4. Expected effect on run 42517: DR1 reads "0 barred sentence(s); 4 layer point(s)", DR2 reads "1 barred sentence(s); 1 layer point(s)". Not changed: the BARRED MOVE VOID line, the KEPT clause, every B Build and B Extract node, the note a seat receives, and when a re-call is sent. (plan rev 0, heading 1, ask633/w4/plan633.md md5 0f6984af)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it" at 06:14 CST 2026-11-25 on W4's card (Wall 12010; audit 42142 by W4's post), engine 3b72583c to ccaf4660, and read back PASS by W1 (Wall 12011: live ccaf4660 active, 423 nodes, node-equal to the target 7b29b0bc, connections equal, only Build Save Body differs from 3b72583c, t633 21 of 21 on the live engine, standing set 31 PASS 0 FAIL). One statement in Build Save Body changed, with one guarded read of D4B Build's press_open; the child aad0ad9c is unchanged. IN PART, because no run has been made since the write: the objective is shown only by a run in which a round is re-called. Offline (W4's build b1, rebuilt by W1 from its own fetch, Wall 12000): on the stored bars of run 42517 DR1 prints "0 barred sentence(s); 4 layer point(s)" and DR2 prints "1 barred sentence(s); 1 layer point(s)"; every line, VOID lines included, equals the base outside the label and the SENT BACK part; the synthetic cases pass (barred only, layers only, both, CR4 with press_open 3, CR4 with D4B Build not run, no layers field, layers.first null, not resent). W1's N1 on the plan (three B Extracts never name "layers" in their code) was met: layers.first is present in the stored bar of all seven Extracts of 42517. Lines stored before the write keep the old label. NOT SEARCHED by W4: dashboard pages that may parse the line's text. NOT CHECKED by W1: the plan's counts of 59 stored re-call lines and 30 reading "SENT BACK: 0 sentence(s)". Open: two clean live runs with a re-call.$t$,
  '11996, 11998, 12000, 12010, 12011',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo582TraRkDasFGGatnZsUqY6k, "Write ASK 633 so the row names why each round was sent back?"): he pressed "Write it" at 06:14 CST 2026-11-25 (press time from Wall 12010). W3 read the card's question and options in W4's thread; W3 did not read the press itself. There was no build card: the build was offline files only, and the card came after the build grade.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 633 so the row names why each round was sent back?", "options": {"Write it": "I change one line in the engine's Build Save Body. Re-call lines then give barred sentences, layer points, and on CR4 pressed verses. W1 reads it back. Undo restores 3b72583c.", "Hold": "The engine stays as it is. A layer-point re-call keeps reading as a barred-move re-call that sent back 0 sentences."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo582TraRkDasFGGatnZsUqY6k", "press_time": "06:14 CST 2026-11-25", "source": "the card as stored in W4's thread, read by W3; press time from Wall 12010."}$j$::jsonb,
  'W4',
  $j${"md5": "0f6984afe6189aa4bd0c4ad5b9474cd2", "path": "ask633/w4/plan633.md", "note": "plan rev 0, graded PASS WITH N1 by W1 (Wall 11996); N1 was met in the build (Wall 11998, 12000).", "source": "md5sum by W3; Wall 11996"}$j$::jsonb,
  $j$[{"path": "ask633/w4/b1/b633.cjs", "md5": "355e577a199ae76f3c3b6501ba537ca6", "what": "build script"}, {"path": "ask633/w4/b1/tg/target_engine_633.json", "md5": "7b29b0bc0729c4f5e78b2f5dc3f65e34", "what": "target engine"}, {"path": "ask633/w4/b1/t633.cjs", "md5": "ac346f8364f41f060620d1ec8f079784", "what": "test"}, {"path": "ask633/w4/b1/tg/out_t633.txt", "md5": "123085c77f5a72866c2b297611e9de37", "what": "test output"}, {"path": "ask633/w4/b1/fx/r42517_bars.json", "md5": "eee4508ccc1662e6de8a28d63c709bc4", "what": "fixture: the seven B Extract bars and D4B Build of run 42517"}, {"path": "ask633/w4/write/write633.sh", "md5": "080e3ec5b27ca899769215ca002bed61", "what": "write script"}, {"path": "ask633/w4/write/write633_run.txt", "md5": "d82fd0d522300ed20f05265c6b68c4f9", "what": "write script output"}, {"path": "ask633/w4/write/fetchback_eng_633.json", "md5": "6072252d1a1282903664737d219da256", "what": "fetch-back after the write"}]$j$::jsonb,
  $j${"engine": "ask633/w4/write/revert_eng_633.json, md5 7d78f5283288cb4fa1f9c26c12c2ea83 (restores 3b72583c)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12010; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (plan rev 0)", "wall_id": 11996, "md5_graded": "0f6984af", "verdict_norm": "PASS", "source": "Wall 11996"}, {"seat": "W1", "verdict": "PASS (build b1)", "wall_id": 12000, "md5_graded": "7b29b0bc0729c4f5e78b2f5dc3f65e34", "verdict_norm": "PASS", "source": "Wall 12000"}]$j$::jsonb,
  ARRAY['7b29b0bc0729c4f5e78b2f5dc3f65e34'], '[42142]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, node Build Save Body", "before": "version 3b72583c; the re-call line reads \"BARRED MOVE RE-CALL (pkgBAR) ... SENT BACK: <n> sentence(s)\"", "after": "version ccaf4660; the line reads \"ROUND RE-CALL (pkgBAR, pkgLAYB) ... SENT BACK: <n> barred sentence(s); <m> layer point(s)\", plus \"; <k> pressed verse(s) with no ANSWER line\" on CR4; m from the B Extract's layers.first items, k from D4B Build press_open by the isExecuted guard. 423 nodes, connections equal."}]$j$::jsonb,
  $j$[{"name": "t633.cjs on the build", "result": "ALL PASS (21): N1 layers.first present in all seven 42517 bars; C1 DR1 and DR2 of 42517; C2 synthetic cases; C4 one line changed, tagged ASK 633, one new catch in the guard form", "source": "Wall 11998; rebuilt and rerun by W1, Wall 12000"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), on the fetch-back (W4, Wall 12010) and on live (W1, Wall 12011); Library Check pair PASSES", "source": "Wall 11998, 12000, 12010, 12011"}, {"name": "NOT RUN", "result": "any live call; the plan needs none (the stored node outputs are the test)", "source": "plan633.md heading 6"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (live ccaf4660, active, 423 nodes, node-equal to target 7b29b0bc, connections equal; only Build Save Body differs from 3b72583c; t633 21 of 21 on live; standing 31 PASS 0 FAIL)", "wall_id": 12011, "source": "Wall 12011 (commit 167cabad)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "on the first run with any round re-call: the row carries \"ROUND RE-CALL (pkgBAR, pkgLAYB)\" lines whose barred and layer counts equal that round's B Build why, and no line reads \"SENT BACK: 0 sentence(s)\".", "not_shown": "the statement on a live run.", "source": "plan633.md heading 6"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Drafted by W3: one pair on part 06.0 (version 242, 24,197 characters), file manual1123/w3/a633/em_pairs_633_draft1.json; preview 25,688 characters, md5 9f478e3e2267497767f68df37c31291e, would be version 324; one sub-bullet of 1,491 characters added under BARRED MOVES, nothing removed. It waits on W1's grade and the operator's card. A revision row is owed when it is written."}$j$::jsonb,
  'read back', $j$[11996, 11998, 12000, 12010, 12011]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built (build b1) and wrote ASK 633 on the operator's card", "wall_id": 12010}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
